115	{
116	    // Both entry points, Home and the printer menu, belong to the shell.
117	    ShellController* shell = installed_shell();
118	    if (!shell || !shell->agent_pane())
119	        throw std::logic_error("Add a printer opened without the JusPrin shell installed");
120	
121	    OpenAIPrinterRecognitionConfig config;
122	    if (wxGetApp().app_config) {
123	        const std::string consent = wxGetApp().app_config->get("jusprin_agent", "cloud_consent");
124	        if (consent == "true" || consent == "1")
125	            config.api_key = Agent::load_provider_api_key(wxGetApp().app_config, "openai");
126	        const std::string model = wxGetApp().app_config->get("jusprin_agent", "model");
127	        if (!model.empty()) config.model = model;
128	    }
129	    auto recognition = std::make_unique<OpenAIPrinterRecognition>(std::move(config), Agent::make_openai_http_transport());
130	    // The controller is built from `apply`, so the flow it answers for is
131	    // filled in once it exists; it outlives every call, which only happens
132	    // inside dialog.ShowModal() below.
133	    PrinterSetupController* flow = nullptr;
134	    auto apply = [&plater, &flow](const PrinterCandidate& candidate, std::string& error) {
135	        return add_printer(plater, candidate, flow->evidence().discovered_device, error);
136	    };
137	    auto controller = std::make_unique<PrinterSetupController>(PrinterCatalog::load(Slic3r::resources_dir()),
138	                                                                std::move(recognition), std::move(apply));
139	    flow = controller.get();
140	    // The same answer the Agent panel gives when it shows its empty state.
141	    const bool agent_connected =
142	        shell->agent_pane()->web_view().host().availability() == Agent::AgentAvailability::Ready;
143	    auto connect = [](const DiscoveredPrinter& printer, const std::string& code, wxString& error) {
144	        return SetupCommands::set_printer_access_code(printer.stable_id, code, error);
145	    };
146	    // Builds a second, throwaway AgentWebView the first time "Set up the
147	    // agent" is clicked: its own independent AgentService/AgentSetupService
148	    // (never the docked pane's), and deliberately no start_mcp() call, since
149	    // a setup-only surface has no need to announce itself for MCP discovery
150	    // or contend with the docked pane's port/discovery file.
151	    auto make_setup_webview = [&theme, dark, shell](wxWindow* parent) {
152	        Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
153	        auto webview = std::make_unique<AgentWebView>(
154	            parent, theme, *shell->workspace(), *shell->persistence(), runtime.availability,
155	            std::move(runtime.service), runtime.setup, /*embedded=*/true);
156	        webview->apply_appearance(dark);
157	        webview->SetName(_L("Agent setup"));
158	        return webview;
159	    };
160	
161	    ModalScrim scrim(owner, theme.palette(dark), theme.metrics().printer_setup.scrim_alpha);
162	    PrinterSetupDialog dialog(scrim.owner_or(owner), theme, dark, std::move(controller), discover_printers(),
163	                              agent_connected, make_setup_webview, connect,
164	                              [shell] { shell->mark_agent_config_possibly_changed(); });
165	    dialog.ShowModal();
