/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> for
   the `font` shorthand of each type role, and the --project-card-*,
   --printer-card-* and --status-dot-* card geometry. Padding, margin, and gap
   stay literal but must sit on the spacing scale. styles.test.ts fails the
   build on any literal outside those rules. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and the web view renders in a separate process
   that cannot see it. The Latin subset shared with the Agent page is embedded
   so Home uses the same face as the native shell; CJK text falls through to
   the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-canvas);
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.app {
  display: flex;
  height: 100%;
  min-width: 0;
}

.app.connecting {
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 8px;
}

  color: var(--text-secondary);
  background: transparent;
  border: 1px dashed var(--border-subtle);
}

.add-printer:hover {
  background: var(--action-secondary-hover);
}

/* The gallery's scroller sits right beside the rail's divider, so a platform
   scrollbar reads as a second, heavier line. It is drawn as a thin subtle
   thumb over no track instead, leaving one divider on screen. */
.gallery,
.printer-column {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

.gallery::-webkit-scrollbar,
.printer-column::-webkit-scrollbar {
  width: 8px;
}

.gallery::-webkit-scrollbar-track,
.printer-column::-webkit-scrollbar-track {
  background: transparent;
}

/* Transparent at rest: the design draws one divider beside the rail, and a
   thumb sitting against it reads as a second heavier line. It appears when the
   pointer is over the surface it scrolls. */
.gallery::-webkit-scrollbar-thumb,
.printer-column::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: var(--radius-pill);
}

.gallery:hover::-webkit-scrollbar-thumb,
.printer-column:hover::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
}

.gallery::-webkit-scrollbar-thumb:hover,
.printer-column::-webkit-scrollbar-thumb:hover {
  background: var(--border-strong);
}

/* Glyphs take the size and colour of the text beside them. */
.glyph {
  flex: 0 0 auto;
  width: var(--glyph-size);
  height: var(--glyph-size);
}

.printer-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.printer-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The header row ends in the status dot and the printer's actions menu. */
.printer-head-end {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.printer-actions {
  position: relative;
  display: flex;
}

/* A quiet icon button: the menu is secondary to the card it sits on. */
.printer-menu-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  color: var(--text-secondary);
