491	void ShellController::on_page_changed()
492	{
493	    if (!m_installed || m_home == nullptr || m_tabpanel == nullptr)
494	        return;
495	    const bool home = m_tabpanel->GetSelection() == MainFrame::tpHome;
496	    if (home)
497	        m_home->refresh();
498	    // A throwaway setup webview elsewhere (the Add a printer dialog) may have
499	    // written a working agent config since the docked pane last checked; push
500	    // it in now, the same "refresh on the way in" pattern as Home's gallery
501	    // above, rather than reloading the page or polling continuously.
502	    if (m_agent_config_possibly_changed) {
503	        m_agent_config_possibly_changed = false;
504	        Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
505	        m_agent_pane->web_view().host().set_agent(std::move(runtime.service), runtime.availability);
506	    }
507	    // Home and the Notebook share the workspace slot, so exactly one is shown.
508	    // The Notebook is only hidden while Home is the selection: post_init
509	    // selects the Prepare tab to map the GL canvas before it initialises
510	    // OpenGL, and this handler runs on that selection, so the Notebook is
511	    // shown at the moment the canvas has to be on screen.
512	    // The header belongs to the workspace: its controls act on the open
513	    // project, so Home, which has no project in front, shows no header.
514	    m_home->Show(home);
515	    m_tabpanel->Show(!home);
516	    m_status_row->Show(!home);
517	    m_frame->Layout();
518	    set_agent_pane_collapsed(home ? true : m_agent_pane_user_collapsed);
519	}

