23	      <PrinterGlyph />
24	      <span className="printer-name">{printer.name}</span>
25	    </span>
26	  );
27	  // A LAN-only device offers none of the actions; a menu of disabled rows
28	  // would be a button that does nothing, so it has none.
29	  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
30	  const end = (
31	    <span className="printer-head-end">
32	      <span className={printing ? 'status-dot printing' : 'status-dot'} aria-hidden="true" />
33	      {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
34	    </span>
35	  );
36	  if (!printing) {
37	    return (
38	      <div className="printer-card collapsed">
39	        {name}
40	        {end}
41	      </div>
42	    );
43	  }
44	  return (
45	    <div className="printer-card">
46	      <div className="printer-head">
47	        {name}
48	        {end}
49	      </div>
50	      {printer.statusText && <div className="printer-job">{printer.statusText}</div>}
