61	void HomeHost::on_page_message(const std::string& text)
62	{
63	    ++m_received;
64	    json envelope;
65	    try {
66	        envelope = json::parse(text);
67	    } catch (const std::exception&) {
68	        // The page is the only writer on this transport and it sends JSON, so
69	        // a parse failure is a bug in the page rather than a state to recover
70	        // from. Dropping it keeps the bridge up; the page's own handshake
71	        // timeout is what reports a page that cannot talk at all.
72	        return;
73	    }
74	    if (envelope.value("protocol", std::string()) != kProtocolName)
75	        return; // another surface's traffic on the same transport
76	
77	    const std::string type        = envelope.value("type", std::string());
78	    const std::string correlation = envelope.value("id", std::string());
79	    const json        payload     = envelope.value("payload", json::object());
80	
81	    if (type == "hello") {
82	        const json versions    = payload.value("protocolVersions", json::array());
83	        const bool speaks_this = std::any_of(versions.begin(), versions.end(),
84	                                             [](const json& version) { return version == kProtocolVersion; });
85	        if (!speaks_this) {
86	            send("hello_reject", json{{"message", "This build speaks Home protocol version 1."}}, correlation);
87	            return;
88	        }
89	        m_connected = true;
90	        send("hello_ack", json{{"protocolVersion", kProtocolVersion}}, correlation);
91	        push_state();
92	        return;
93	    }
94	
95	    if (!m_connected)
96	        return; // nothing but hello is answered before the handshake
97	
98	    if (type == "state_request")
99	        push_state();
100	    else if (type == "open_project")
101	        m_backend.open_project(payload.value("id", std::string()));
102	    else if (type == "new_project")
103	        m_backend.new_project();
104	    else if (type == "import_project")
105	        m_backend.import_model();
106	    else if (type == "launch_monitor")
107	        m_backend.launch_monitor(payload.value("id", std::string()));
108	    else if (type == "add_printer") {
109	        m_backend.add_printer();
110	        push_state();
111	    }
112	    else if (type == "open_printer_settings" || type == "rename_printer" || type == "remove_printer") {
113	        const std::string id = payload.value("id", std::string());
114	        const std::string problem =
115	            type == "open_printer_settings" ? m_backend.open_printer_settings(id)
116	            : type == "rename_printer"      ? m_backend.rename_printer(id, payload.value("name", std::string()))
117	                                            : m_backend.remove_printer(id);
118	        if (!problem.empty())
119	            send("printer_error", json{{"id", id}, {"message", problem}}, correlation);
120	        // Each can change the rail, including when the person cancelled
121	        // halfway through an Orca prompt, so the page always gets it back.
122	        push_state();
123	    }
124	}
