76	export class SharedBridgeClient {
77	  private readonly protocol: ProtocolIdentity;
78	  private readonly options: BridgeClientOptions;
79	  private nextId = 1;
80	  private handshakeHandle: unknown = null;
81	  private state: ConnectionState = 'connecting';
82	  private transport: Transport | null = null;
83	  private transportAttempts = 0;
84	
85	  constructor(protocol: ProtocolIdentity, options: BridgeClientOptions) {
86	    this.protocol = protocol;
87	    this.options = options;
88	  }
89	
90	  connectionState(): ConnectionState {
91	    return this.state;
92	  }
93	
94	  start(): void {
95	    if (typeof window !== 'undefined') {
96	      window.__jusprinBridge = { deliver: (envelope: unknown) => this.deliver(envelope) };
97	    }
98	    this.beginHandshake();
99	  }
100	
101	  retry(): void {
102	    this.transportAttempts = 0;
103	    this.beginHandshake();
104	  }
105	
106	  private schedule(fn: () => void, ms: number): unknown {
107	    const schedule = this.options.scheduleTimeout ?? ((f, m) => setTimeout(f, m));
108	    return schedule(fn, ms);
109	  }
110	
111	  private cancel(handle: unknown): void {
112	    const cancel = this.options.cancelTimeout ?? ((h) => clearTimeout(h as number));
113	    cancel(handle);
114	  }
115	
116	  private beginHandshake(): void {
117	    this.transport = this.options.getTransport();
118	    if (!this.transport) {
119	      const limit = this.options.transportRetryLimit ?? 40;
120	      if (this.transportAttempts < limit) {
121	        this.transportAttempts += 1;
122	        this.setState('connecting');
123	        this.schedule(() => {
124	          if (this.state === 'connecting' && !this.transport) this.beginHandshake();
125	        }, this.options.transportRetryMs ?? 250);
126	      } else {
127	        this.setState('no-transport', 'The native message handler (window.wx) is not present.');
128	      }
129	      return;
130	    }
131	    this.setState('connecting');
132	    this.post('hello', {
133	      protocolVersions: [this.protocol.version],
134	      capabilities: this.protocol.capabilities,
135	    });
136	    const timeoutMs = this.options.handshakeTimeoutMs ?? 10000;
137	    if (this.handshakeHandle !== null) this.cancel(this.handshakeHandle);
138	    this.handshakeHandle = this.schedule(() => {
139	      if (this.state === 'connecting') {
140	        this.setState('timeout', 'The native host did not answer the hello handshake.');
141	      }
142	    }, timeoutMs);
143	  }
144	
145	  send(type: string, payload: unknown): void {
146	    this.post(type, payload);
147	  }
148	
149	  private post(type: string, payload: unknown): void {
150	    if (!this.transport) return;
151	    const envelope: Envelope = {
152	      protocol: this.protocol.name,
153	      version: this.protocol.version,
154	      id: `w-${this.nextId++}`,
155	      type,
156	      payload,
157	    };
158	    this.transport.post(JSON.stringify(envelope));
159	  }

